const body = $input.first().json.body ?? {};
const errors = [];
const type = String(body.event_type ?? '').toLowerCase().trim();
if (!['price_change', 'stock_change'].includes(type)) errors.push('event_type must be price_change or stock_change');
const sku = String(body.sku ?? '').trim();
if (!sku) errors.push('sku is required');
const supplier = String(body.supplier ?? '').trim();
if (!supplier) errors.push('supplier is required');

const num = (v) => (v === null || v === undefined || v === '' || Number.isNaN(Number(v))) ? null : Number(v);
let oldVal = null, newVal = null;
if (type === 'price_change') {
  oldVal = num(body.old_price); newVal = num(body.new_price);
  if (oldVal === null || oldVal < 0) errors.push('old_price must be a non-negative number');
  if (newVal === null || newVal < 0) errors.push('new_price must be a non-negative number');
} else if (type === 'stock_change') {
  oldVal = num(body.old_stock); newVal = num(body.new_stock);
  if (oldVal === null || oldVal < 0 || !Number.isInteger(oldVal)) errors.push('old_stock must be a non-negative integer');
  if (newVal === null || newVal < 0 || !Number.isInteger(newVal)) errors.push('new_stock must be a non-negative integer');
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const receivedAt = new Date().toISOString();

if (errors.length) {
  return [{ json: {
    valid: false, errors,
    message: '⛔ <b>Malformed supplier webhook rejected</b>\n' + errors.map(e => '• ' + esc(e)).join('\n') +
             '\n\n<code>' + esc(JSON.stringify(body).slice(0, 500)) + '</code>'
  } }];
}

const pct = oldVal === 0 ? null : Math.round(((newVal - oldVal) / oldVal) * 1000) / 10;
const currency = String(body.currency ?? '').trim();
const name = String(body.product_name ?? '').trim();
let severity = 'info';
if (type === 'stock_change') severity = newVal === 0 ? 'critical' : (newVal <= 5 ? 'warning' : 'info');
else if (pct !== null && Math.abs(pct) >= 20) severity = 'critical';
else if (pct !== null && Math.abs(pct) >= 10) severity = 'warning';

const icon = { info: 'ℹ️', warning: '⚠️', critical: '🚨' }[severity];
const arrow = newVal > oldVal ? '📈' : (newVal < oldVal ? '📉' : '➖');
const label = type === 'price_change' ? 'Price change' : 'Stock change';
const fmt = (v) => type === 'price_change' ? (currency ? currency + ' ' : '') + v : v + ' units';
const message = `${icon} <b>${label}</b> ${arrow}\n` +
  `<b>Supplier:</b> ${esc(supplier)}\n<b>SKU:</b> ${esc(sku)}` + (name ? `\n<b>Product:</b> ${esc(name)}` : '') +
  `\n<b>Was:</b> ${esc(fmt(oldVal))}\n<b>Now:</b> ${esc(fmt(newVal))}` +
  (pct !== null ? `\n<b>Change:</b> ${pct > 0 ? '+' : ''}${pct}%` : '') +
  `\n<b>Severity:</b> ${severity}`;

return [{ json: {
  valid: true, errors: [],
  event_type: type, sku, supplier, product_name: name,
  old_value: oldVal, new_value: newVal, change_pct: pct, currency, severity,
  received_at: receivedAt, raw_payload: JSON.stringify(body), message
} }];
